INSERT INTO tourist_spots (district_id, name, description, category, latitude, longitude, rating, entry_fee, visit_duration) VALUES
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Visakhapatnam' AND s.name='Andhra Pradesh'), 'RK Beach Vizag', 'A lively city beach along Beach Road, popular for sunrise walks and submarine museum visits nearby.', 'Beach', 17.714500, 83.315700, 4.3, 'Free', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Visakhapatnam' AND s.name='Andhra Pradesh'), 'Kailasagiri Hill', 'A hilltop park with panoramic bay views, ropeway rides, and giant Shiva-Parvati statues.', 'Viewpoint', 17.749200, 83.341500, 4.4, 'Rs. 50', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Chittoor' AND s.name='Andhra Pradesh'), 'Tirumala Balaji Temple', 'One of the world''s richest and most visited temples, dedicated to Lord Venkateswara atop Tirumala hills.', 'Temple', 13.683100, 79.347200, 4.9, 'Free', '4-6 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Guntur' AND s.name='Andhra Pradesh'), 'Amaravati Stupa', 'Ancient 2nd-century Buddhist mahachaitya with carved limestone panels and a modern museum.', 'Heritage', 16.574600, 80.357000, 4.3, 'Free', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Tawang' AND s.name='Arunachal Pradesh'), 'Tawang Monastery', 'India''s largest monastery, a 400-year-old Gelugpa citadel overlooking the Tawang valley.', 'Monastery', 27.586700, 91.857200, 4.8, 'Free', '3-4 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Tawang' AND s.name='Arunachal Pradesh'), 'Sela Pass', 'A high-altitude pass at 13,700 ft with the sacred Sela Lake, often snow-covered.', 'Nature', 27.509000, 92.101700, 4.6, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='West Kameng' AND s.name='Arunachal Pradesh'), 'Dirang Valley', 'A serene alpine valley of apple orchards, hot springs, and the Dirang Dzong fortress.', 'Valley', 27.360000, 92.240000, 4.5, 'Free', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Papum Pare' AND s.name='Arunachal Pradesh'), 'Ita Fort', 'A 14th-century brick fort in Itanagar built by the Jitari kings, among the oldest in the region.', 'Heritage', 27.100000, 93.616700, 4.0, 'Free', '1-2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Kamrup Metropolitan' AND s.name='Assam'), 'Kamakhya Temple', 'A revered Shakti shrine atop Nilachal Hill, center of the Ambubachi festival.', 'Temple', 26.166400, 91.705600, 4.7, 'Free', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Kamrup Metropolitan' AND s.name='Assam'), 'Umananda Island', 'The world''s smallest inhabited river island, with a Shiva temple mid-Brahmaputra.', 'Spiritual', 26.191700, 91.745800, 4.3, 'Free', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Golaghat' AND s.name='Assam'), 'Kaziranga Central Range', 'UNESCO grasslands sheltering two-thirds of the world''s one-horned rhinos, best by jeep safari.', 'Wildlife', 26.577500, 93.171100, 4.8, 'Rs. 100', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Baksa' AND s.name='Assam'), 'Manas National Park', 'A UNESCO tiger and elephant reserve in Himalayan foothills, home to golden langurs.', 'Wildlife', 26.725000, 90.950000, 4.6, 'Rs. 200', 'Full day'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Patna' AND s.name='Bihar'), 'Golghar', 'A 1786 beehive-shaped granary with panoramic Ganga views from its spiral stairway top.', 'Heritage', 25.620000, 85.140000, 4.0, 'Free', '1 hour'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Patna' AND s.name='Bihar'), 'Patna Museum', 'A colonial museum of Mauryan Didarganj Yakshi, fossils, and Mughal paintings.', 'Museum', 25.620900, 85.143800, 4.2, 'Rs. 15', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Gaya' AND s.name='Bihar'), 'Mahabodhi Temple', 'The UNESCO temple marking Buddha''s enlightenment, with the sacred Bodhi Tree.', 'Temple', 24.696000, 84.993000, 4.9, 'Free', '3-4 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Nalanda' AND s.name='Bihar'), 'Nalanda Ruins', 'Excavated remains of the ancient world''s greatest residential university (5th-12th century).', 'Heritage', 25.136700, 85.443700, 4.6, 'Rs. 40', '2-3 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Raipur' AND s.name='Chhattisgarh'), 'Mahant Ghasidas Museum', 'A heritage museum of tribal art, inscriptions, and natural history in Raipur.', 'Museum', 21.237900, 81.639000, 4.1, 'Rs. 10', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Bastar' AND s.name='Chhattisgarh'), 'Chitrakote Falls', 'India''s widest waterfall on the Indravati, called the Niagara of India.', 'Waterfall', 19.207200, 81.699600, 4.7, 'Free', '3-4 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Bilaspur' AND s.name='Chhattisgarh'), 'Ratanpur Mahamaya Temple', 'An 11th-century Kalachuri temple complex, a major Shakti pilgrimage center.', 'Temple', 22.296800, 82.165000, 4.3, 'Free', '2 hours'),
((SELECT d.id FROM districts d JOIN states s ON d.state_id=s.id WHERE d.name='Ahmedabad' AND s.name='Gujarat'), 'Sabarmati Ashram', 'Gandhi''s 1917 ashram on the Sabarmati, origin of the Dandi March.', 'Heritage', 23.060700, 72.580600, 4.6, 'Free', '2 hours'),
